def _get_val(self, dtype, optional=False, arraydims=()):
    # Unpack one value of the specified type from the table,
    # and advance the position pointer appropriately.  dtype
    # uses values compatible with numpy, ie i4, f4, etc.
    string_val = False
    if dtype == 'i4':
        unpack = self._unpack_int
    elif dtype == 'i8':
        unpack = self._unpack_long
    elif dtype == 'f4':
        unpack = self._unpack_float
    elif dtype == 'f8':
        unpack = self._unpack_double
    elif dtype == 'b':
        unpack = self._unpack_byte
    elif dtype[0] == 'S':
        unpack = None
        string_val = True
    else:
        raise RuntimeError("Unknown data dtype (dtype='%s')" % dtype)
    try:
        if optional:
            has_data = self._readtab(1) != b'\0'
            if not has_data:
                # Return some default values..
                if string_val:
                    return ''
                else:
                    return 0
        ndim = len(arraydims)
        if string_val: 
            ndim = 1
        dims = []
        for i in range(ndim):
            nval = self._unpack_int.unpack_from(self._readtab(4))[0]
            dims.append(nval)
        if string_val:
            val = self._readtab(dims[0])
            # Return a str in python3
            if val is not None and not isinstance(val,str):
                val = val.decode('utf-8')
            return val
        dsize = unpack.size
        if ndim:
            ntot = numpy.product(dims)
            return numpy.array([unpack.unpack_from(self._readtab(dsize))[0]
                    for i in range(ntot)]).reshape(dims)
        else:
            return unpack.unpack_from(self._readtab(dsize))[0]
    except struct.error:
        # Not enough bytes to unpack probably means we are at the end of
        # the table.
        return None

def make_new_dset(parent, shape=None, dtype=None, data=None,
                  chunks=None, compression=None, shuffle=None,
                  fletcher32=None, maxshape=None, compression_opts=None,
                  fillvalue=None, scaleoffset=None, track_times=None,
                  external=None, track_order=None, dcpl=None):
    """ Return a new low-level dataset identifier

    Only creates anonymous datasets.
    """

    # Convert data to a C-contiguous ndarray
    if data is not None and not isinstance(data, Empty):
        from . import base
        # normalize strings -> np.dtype objects
        if dtype is not None:
            _dtype = numpy.dtype(dtype)
        else:
            _dtype = None

        # if we are going to a f2 datatype, pre-convert in python
        # to workaround a possible h5py bug in the conversion.
        is_small_float = (_dtype is not None and
                          _dtype.kind == 'f' and
                          _dtype.itemsize == 2)
        data = numpy.asarray(data, order="C",
                             dtype=(_dtype if is_small_float
                                    else base.guess_dtype(data)))

    # Validate shape
    if shape is None:
        if data is None:
            if dtype is None:
                raise TypeError("One of data, shape or dtype must be specified")
            data = Empty(dtype)
        shape = data.shape
    else:
        shape = tuple(shape)
        if data is not None and (numpy.product(shape, dtype=numpy.ulonglong) != numpy.product(data.shape, dtype=numpy.ulonglong)):
            raise ValueError("Shape tuple is incompatible with data")

    tmp_shape = maxshape if maxshape is not None else shape
    # Validate chunk shape
    if isinstance(chunks, tuple) and any(
        chunk > dim for dim, chunk in zip(tmp_shape, chunks) if dim is not None
    ):
        errmsg = "Chunk shape must not be greater than data shape in any dimension. "\
                 "{} is not compatible with {}".format(chunks, shape)
        raise ValueError(errmsg)

    if isinstance(dtype, Datatype):
        # Named types are used as-is
        tid = dtype.id
        dtype = tid.dtype  # Following code needs this
    else:
        # Validate dtype
        if dtype is None and data is None:
            dtype = numpy.dtype("=f4")
        elif dtype is None and data is not None:
            dtype = data.dtype
        else:
            dtype = numpy.dtype(dtype)
        tid = h5t.py_create(dtype, logical=1)

    # Legacy
    if any((compression, shuffle, fletcher32, maxshape, scaleoffset)) and chunks is False:
        raise ValueError("Chunked format required for given storage options")

    # Legacy
    if compression is True:
        if compression_opts is None:
            compression_opts = 4
        compression = 'gzip'

    # Legacy
    if compression in _LEGACY_GZIP_COMPRESSION_VALS:
        if compression_opts is not None:
            raise TypeError("Conflict in compression options")
        compression_opts = compression
        compression = 'gzip'

    dcpl = filters.fill_dcpl(
        dcpl or h5p.create(h5p.DATASET_CREATE), shape, dtype,
        chunks, compression, compression_opts, shuffle, fletcher32,
        maxshape, scaleoffset, external)

    if fillvalue is not None:
        fillvalue = numpy.array(fillvalue)
        dcpl.set_fill_value(fillvalue)

    if track_times in (True, False):
        dcpl.set_obj_track_times(track_times)
    elif track_times is not None:
        raise TypeError("track_times must be either True or False")
    if track_order == True:
        dcpl.set_attr_creation_order(
            h5p.CRT_ORDER_TRACKED | h5p.CRT_ORDER_INDEXED)
    elif track_order == False:
        dcpl.set_attr_creation_order(0)
    elif track_order is not None:
        raise TypeError("track_order must be either True or False")

    if maxshape is not None:
        maxshape = tuple(m if m is not None else h5s.UNLIMITED for m in maxshape)

    if isinstance(data, Empty):
        sid = h5s.create(h5s.NULL)
    else:
        sid = h5s.create_simple(shape, maxshape)


    dset_id = h5d.create(parent.id, None, tid, sid, dcpl=dcpl)

    if (data is not None) and (not isinstance(data, Empty)):
        dset_id.write(h5s.ALL, h5s.ALL, data)

    return dset_id

