    correlation type (cross or auto)."""
    return numpy.product(self.mshape(corr))

def calculate_saturation(self, image_group, workspace):
    """Count the # of pixels at saturation"""

    result = []
    for image_name in self.images_to_process(image_group, workspace):
        image = workspace.image_set.get_image(image_name, must_be_grayscale=True)
        pixel_data = image.pixel_data
        if image.has_mask:
            pixel_data = pixel_data[image.mask]
        pixel_count = numpy.product(pixel_data.shape)
        if pixel_count == 0:
            percent_maximal = 0
            percent_minimal = 0
        else:
            number_pixels_maximal = numpy.sum(pixel_data == numpy.max(pixel_data))
            number_pixels_minimal = numpy.sum(pixel_data == numpy.min(pixel_data))
            percent_maximal = (
                100.0 * float(number_pixels_maximal) / float(pixel_count)
            )
            percent_minimal = (
                100.0 * float(number_pixels_minimal) / float(pixel_count)
            )
        percent_maximal_name = "{}_{}_{}".format(
            C_IMAGE_QUALITY, F_PERCENT_MAXIMAL, image_name
        )
        percent_minimal_name = "{}_{}_{}".format(
            C_IMAGE_QUALITY, F_PERCENT_MINIMAL, image_name
        )
        workspace.add_measurement(
            "Image", percent_maximal_name, percent_maximal,
        )
        workspace.add_measurement(
            "Image", percent_minimal_name, percent_minimal,
        )
        result += [
            ["{} maximal".format(image_name), "{:.1f} %".format(percent_maximal)],
            ["{} minimal".format(image_name), "{:.1f} %".format(percent_minimal)],
        ]
    return result

def calculate_power_spectrum(self, image_group, workspace):
    result = []
    for image_name in self.images_to_process(image_group, workspace):
        image = workspace.image_set.get_image(image_name, must_be_grayscale=True)

        if image.dimensions == 3:
            # TODO: calculate "radial power spectrum" for volumes.
            continue

        pixel_data = image.pixel_data

        if image.has_mask:
            pixel_data = numpy.array(pixel_data)  # make a copy
            masked_pixels = pixel_data[image.mask]
            pixel_count = numpy.product(masked_pixels.shape)
            if pixel_count > 0:
                pixel_data[~image.mask] = numpy.mean(masked_pixels)
            else:
                pixel_data[~image.mask] = 0

        radii, magnitude, power = centrosome.radial_power_spectrum.rps(pixel_data)
        if sum(magnitude) > 0 and len(numpy.unique(pixel_data)) > 1:
            valid = magnitude > 0
            radii = radii[valid].reshape((-1, 1))
            power = power[valid].reshape((-1, 1))
            if radii.shape[0] > 1:
                idx = numpy.isfinite(numpy.log(power))
                powerslope = scipy.linalg.basic.lstsq(
                    numpy.hstack(
                        (
                            numpy.log(radii)[idx][:, numpy.newaxis],
                            numpy.ones(radii.shape)[idx][:, numpy.newaxis],
                        )
                    ),
                    numpy.log(power)[idx][:, numpy.newaxis],
                )[0][0]
            else:
                powerslope = 0
        else:
            powerslope = 0

        workspace.add_measurement(
            "Image",
            "{}_{}_{}".format(C_IMAGE_QUALITY, F_POWER_SPECTRUM_SLOPE, image_name),
            powerslope,
        )
        result += [
            [
                "{} {}".format(image_name, F_POWER_SPECTRUM_SLOPE),
                "{:.1f}".format(float(powerslope)),
            ]
        ]
    return result

def val2array(value, withNone=True, withScalar=True, length=2):
    """Helper function: converts different input to a numpy array.

    Raises informative error messages if input is invalid.

    withNone: True/False. should 'None' be passed?
    withScalar: True/False. is a scalar an accepted input?
        Will be converted to array of this scalar
    length: False / 2 / 3. Number of elements input should have or be
        converted to. Might be False (do not accept arrays or convert to such)
    """
    if value is None:
        if withNone:
            return None
        else:
            raise ValueError('Invalid parameter. None is not accepted as '
                             'value.')
    value = numpy.array(value, float)
    if numpy.product(value.shape) == 1:
        if withScalar:
            # e.g. 5 becomes array([5.0, 5.0, 5.0]) for length=3
            return numpy.repeat(value, length)
        else:
            msg = ('Invalid parameter. Single numbers are not accepted. '
                   'Should be tuple/list/array of length %s')
            raise ValueError(msg % str(length))
    elif value.shape[-1] == length:
        return numpy.array(value, float)
    else:
        msg = 'Invalid parameter. Should be length %s but got length %s.'
        raise ValueError(msg % (str(length), str(len(value))))

def get_dataset_slice(self, in_dataset_obj, dataset_info, in_data_idx, out_shape, inp_filename=""):
    """Copys dataset values from one dataset object to another, but only certain indexes along a
    specific dimension of the data"""

    # Determine how to extact data other than the splice dimension
    in_dataset_indexes = dataset_info.input_data_indexes(in_dataset_obj, in_data_idx)

    # Obtain selected data for copying into output dataset
    try:
        if len(in_dataset_indexes) == 1 and not isinstance(in_dataset_indexes[0], slice):
            in_data = in_dataset_obj[:][numpy.array(in_dataset_indexes[0])]
        else:
            in_data = in_dataset_obj[:][tuple(in_dataset_indexes)]
    except IOError as exc:
        raise IOError("Can not read dataset %s from file %s: %s" % (dataset_info.inp_name, inp_filename, exc))

    # Set sliced data into output dataset
    if numpy.product(in_data.shape) > numpy.product(out_shape):
        self.logger.warning("Dataset %s requires destructive resizing" % (dataset_info.out_name))
        self.logger.debug("At indexes %s resizing source data of shape %s to %s." % (in_data_idx, in_data.shape, out_shape)) 
        stored_data = numpy.resize(in_data, out_shape)
    else:
        stored_data = in_data.reshape(out_shape)

    return stored_data

