def para_segments(self):
    vector = []
    for idx, key in enumerate(sorted(list(self._parameters.keys()))):
        vector.append(numpy.full(fill_value = idx, shape=(numpy.product(self._parameters[key].shape), ), dtype="int32"))
    return numpy.concatenate(vector, axis=0)

def from_vector(self, vector, shapes):
    self._parameters = dict()
    start = 0
    for key, shape in shapes:
        end = start + numpy.product(shape)
        self._parameters[key] = numpy.reshape(vector[start:end], shape)
        start = end
    if(end != len(vector)):
        raise Exception("Mismatch shape info and vector. Len of shape: %d; Len of vector: %d"%(end, len(vector)))

def from_vector_static(self, vector, shapes):
    self._static_parameters = dict()
    start = 0
    for key, shape in shapes:
        end = start + numpy.product(shape)
        self._static_parameters[key] = numpy.reshape(vector[start:end], shape)
        start = end
    if(end != len(vector)):
        raise Exception("Mismatch shape info and vector. Len of shape: %d; Len of vector: %d"%(end, len(vector)))

def _compute_probability_of_success(self, failure_components):
  assert isinstance(failure_components, FailureListProductComponents)
  return numpy.product(failure_components.poss, axis=0)

def __len__(self):
    length = 0
    for subspace in self.space.subspaces():
        if not subspace:
            continue
        sizes = [len(v_list) if isinstance(v_list, Distribution) else 1 for v_list in subspace]
        length += numpy.product(sizes)

    return length

def __getitem__(self, i):
    # This is a reimplementation of scikit-learn ParameterGrid __getitem__
    l = len(self)
    if -l <= i < 0:
        i += l
    elif i < -l or i >= l:
        raise IndexError("list index out of range")

    for subspace in self.space.subspaces():
        # XXX: could memoize information used here
        sizes = [len(v_list) if isinstance(v_list, Distribution) else 1 for v_list in subspace]
        total = numpy.product(sizes)

        if i >= total:
            # Try the next grid
            i -= total
        else:
            out = list()
            for v_list, n in zip(subspace, sizes):
                i, offset = divmod(i, n)
                if isinstance(v_list, Distribution):
                    out.append(v_list[offset])
                else:
                    out.append(v_list)

            return out

def _is_finished(self):
    masks = self.masks[self.indexes]
    masks = np.sum(masks, axis=0)
    masks[masks > 0] = 1
    area_coverage = np.sum(masks) / np.product(masks.shape)
    print(area_coverage)
    if area_coverage < self.stop_criteria:
        return False
    else:
        return True

def create_from_handles(self, handles, module_num):
    """Fill a module with the information stored in the handles structure for module # ModuleNum

    Returns a module with the settings decanted from the handles.
    If the revision is old, a different and compatible module can be returned.
    """
    self.__module_num = module_num
    idx = module_num - 1
    settings = handles[SETTINGS][0, 0]
    setting_values = []
    self.__notes = []
    if (
            MODULE_NOTES in settings.dtype.fields
            and settings[MODULE_NOTES].shape[1] > idx
    ):
        n = settings[MODULE_NOTES][0, idx].flatten()
        for x in n:
            if isinstance(x, numpy.ndarray):
                if len(x) == 0:
                    x = ""
                else:
                    x = x[0]
            self.__notes.append(x)
    if SHOW_WINDOW in settings.dtype.fields:
        self.__show_window = settings[SHOW_WINDOW][0, idx] != 0
    if BATCH_STATE in settings.dtype.fields:
        # convert from uint8 to array of one string to avoid long
        # arrays, which get truncated by numpy repr()
        self.batch_state = numpy.array(settings[BATCH_STATE][0, idx].tostring())
    setting_count = settings[NUMBERS_OF_VARIABLES][0, idx]
    variable_revision_number = settings[VARIABLE_REVISION_NUMBERS][0, idx]
    module_name = settings[MODULE_NAMES][0, idx][0]
    for i in range(0, setting_count):
        value_cell = settings[VARIABLE_VALUES][idx, i]
        if isinstance(value_cell, numpy.ndarray):
            if numpy.product(value_cell.shape) == 0:
                setting_values.append("")
            else:
                setting_values.append(str(value_cell[0]))
        else:
            setting_values.append(value_cell)
    self.set_settings_from_values(
        setting_values, variable_revision_number, module_name
    )

def get_optimum_size(self, size):
    """
    Gets the nearest optimum image size

    Taken from the casa source code (cleanhelper.py)

    Parameters
    ----------
    size : int
        Target image size in pixels

    Returns
    -------
    optimum_size : int
        Optimum image size nearest to target size

    """
    import numpy

    def prime_factors(n, douniq=True):
        """ Return the prime factors of the given number. """
        factors = []
        lastresult = n
        sqlast=int(numpy.sqrt(n))+1
        if n == 1:
            return([1])
        c=2
        while 1:
             if (lastresult == 1) or (c > sqlast):
                 break
             sqlast=int(numpy.sqrt(lastresult))+1
             while 1:
                 if(c > sqlast):
                     c=lastresult
                     break
                 if lastresult % c == 0:
                     break
                 c += 1
             factors.append(c)
             lastresult /= c
        if (factors==[]): factors=[n]
        return(numpy.unique(factors).tolist() if douniq else factors)

    n = int(size)
    if (n%2 != 0):
        n+=1
    fac=prime_factors(n, False)
    for k in range(len(fac)):
        if (fac[k] > 7):
            val=fac[k]
            while (numpy.max(prime_factors(val)) > 7):
                val +=1
            fac[k]=val
    newlarge=numpy.product(fac)
    for k in range(n, newlarge, 2):
        if ((numpy.max(prime_factors(k)) < 8)):
            return(k)
    return(newlarge)

