def validate_outcome_length(outcomes):
    """
    Validates that all outcomes have the same length.

    """
    # Make sure each outcome is a container.
    try:
        lengths = list(map(len, outcomes))
    except TypeError:
        raise ditException('One or more outcomes is not a container.')
    else:
        outcome_length = lengths[0]

    # Make sure each outcome has the same length.
    equal_lengths = np.alltrue(np.equal(lengths, outcome_length))
    if not equal_lengths:
        raise ditException('Not all outcomes have the same length.')
    else:
        return True

def compare(A, B, ids=None):
    """Safe comparison of general objects

    USAGE:
      compare(A,B)

    DESCRIPTION:
      Return 1 if A and B they are identical, 0 otherwise
    """

    # Keep track of unique id's to protect against infinite recursion
    if ids is None: ids = {}

    # Check if T has already been encountered
    iA = id(A) 
    iB = id(B)     

    if (iA, iB) in ids:
        # A and B have been compared already
        return ids[(iA, iB)]
    else:
        ids[(iA, iB)] = True


    # Check if arguments are of same type
    if type(A) != type(B):
        return False


    # Compare recursively based on argument type
    if isinstance(A, (tuple, list)):
        N = len(A)
        if len(B) != N: 
            identical = False
        else:
            identical = True
            for i in range(N):
                if not compare(A[i], B[i], ids): 
                    identical = False; break

    elif isinstance(A, dict):
        if len(A) != len(B):
            identical = False
        else:
            # Dictionaries are now ordered as of Python 3.7
            # Make dictionary ordering unique 
            #a = list(A.items()); a.sort()    
            #b = list(B.items()); b.sort()

            identical = compare(A, B, ids)

    elif isinstance(A, num.ndarray):
        # Use element by element comparison
        identical = num.alltrue(A==B)

    #elif type(A) == types.InstanceType:
    elif type(A) is type:
        # Take care of special case where elements are instances            
        # Base comparison on attributes
        identical = compare(A.__dict__, 
                            B.__dict__, 
                            ids)
    else:       
        # Fall back to general code
        try:
            identical = (A == B)
        except:
            import pickle
            # Use pickle to compare data
            # The native pickler must be used
            # since the faster cPickle does not 
            # guarantee a unique translation
            # FIXME (Ole): Try to fall back on the dill pickler
            try:
                identical = (pickle.dumps(A,0) == pickle.dumps(B,0))
            except:
                identical = False

    # Record result of comparison and return            
    ids[(iA, iB)] = identical

    return(identical)

def transform(self, A):
    """ Apply cut-below value constraint"""
    if self._excl_mat is None:
        self._make_excl_mat(A.shape)

    if self.axis is None:
        if self.copy:
            return A*((A >= self.value) | self._excl_mat)
        else:
            A *= ((A >= self.value) | self._excl_mat)
            return A
    else:
        if self.copy:
            return A*(_np.alltrue(A < self.value, axis=self.axis, keepdims=True) +
                    (A >= self.value) + self._excl_mat)
        else:
            A *= (_np.alltrue(A < self.value, axis=self.axis, keepdims=True) +
                (A >= self.value) + self._excl_mat)
            return A

