def inv(self):
    """Inverse and return as new matrix."""
    if not numpy.alltrue(self.sizeList[:,0]==self.sizeList[:,1]):
        raise Exception("Cannont inverse a non-square block matrix - please use todense and do it manually")
    newBM=BlockMatrix()
    bl=[]
    for b in self.blockList:
        bl.append(numpy.linalg.inv(b))
    newBM.assign(bl)
    return newBM

def pinv(self,rcond=1e-15):
    """Inverse and return as new matrix."""
    if not numpy.alltrue(self.sizeList[:,0]==self.sizeList[:,1]):
        raise Exception("Cannont inverse a non-square block matrix - please use todense and do it manually")
    newBM=BlockMatrix()
    bl=[]
    for b in self.blockList:
        bl.append(numpy.linalg.pinv(b,rcond))
    newBM.assign(bl)
    return newBM

def transpose(self):
    """Return the transpose of self."""
    if not numpy.alltrue(self.sizeList[:,0]==self.sizeList[:,1]):
        raise Exception("Not yet implemented - transpose of block matrix with non-square blocks - should be easy to do if you need it...")
    newBM=self.copy()
    for b in newBM.blockList:
        b[:]=b.copy().transpose()

def __init__(self, dir, dir_rule="*", excludes=[]):
    raw_classes = [os.path.basename(ii) for ii in glob2.glob(os.path.join(dir, dir_rule))]
    raw_classes = [ii for ii in raw_classes if ii not in excludes]
    is_all_numeric = np.alltrue([str.isnumeric(ii) for ii in raw_classes])

    self.raw_classes = sorted(raw_classes, key=lambda xx: int(xx)) if is_all_numeric else sorted(raw_classes)
    self.classes_2_indices = {ii: id for id, ii in enumerate(self.raw_classes)}
    self.indices_2_classes = {vv: kk for kk, vv in self.classes_2_indices.items()}

def predict_2step(h_decision, h_classif, min_t, data):
    n_test, n_t = data.shape[:2]
    predicted = numpy.zeros((n_test,), dtype=numpy.int32) - 1
    tau = numpy.zeros((n_test,), dtype=numpy.int32) - 1
    for t in range(min_t, n_t):
        if type(h_decision[t]) == numpy.int32:
            if h_decision[t] == 0:
                continue
            else:
                for idx in range(n_test):
                    if predicted[idx] < 0:
                        predicted[idx] = h_classif[t].predict(data[idx, :t])
                        tau[idx] = t
        else:
            dec = h_decision[t].predict(data[:, :t])
            for idx in range(n_test):
                if dec[idx] == 1 and predicted[idx] < 0:
                    predicted[idx] = h_classif[t].predict(data[idx, :t])
                    tau[idx] = t
        if numpy.alltrue(predicted >= 0):
            break
    return predicted, tau

