def isCloseVector(self, ar, eps):
    if eps == 0:
        return self.equalVector(ar)
    diff = ar[1:] - ar[:-1]
    diff2 = self.delta * numpy.ones(self.length - 1)
    try:
        comp = numpy.alltrue(
            numpy.less_equal(
                numpy.absolute(
                    diff2 - diff),
                numpy.absolute(
                    eps * diff2)))
    except ValueError:
        return 0
    return comp

