def apply(self, data):
    # so that correlation matrix calculation doesn't crash
    for ch in data:
        if np.alltrue(ch == 0.0):
            ch[-1] += 0.00001

    data1 = data
    if data1.shape[1] > self.max_hz:
        data1 = Resample(self.max_hz).apply(data1)

    if self.scale_option == 'first_axis':
        data1 = StandardizeFirst().apply(data1)
    elif self.scale_option == 'last_axis':
        data1 = StandardizeLast().apply(data1)

    data1 = CorrelationMatrix().apply(data1)

    if self.with_eigen:
        w = Eigenvalues().apply(data1)

    out = []
    if self.with_corr:
        data1 = upper_right_triangle(data1)
        out.append(data1)
    if self.with_eigen:
        out.append(w)

    for d in out:
        assert d.ndim == 1

    return np.concatenate(out, axis=0)

def test_numpy_subclass_serialization():
    # Check that we can properly serialize subclasses of np.ndarray.
    class CustomNDArray(np.ndarray):
        def __new__(cls, input_array):
            array = np.asarray(input_array).view(cls)
            return array

    def serializer(obj):
        return {'numpy': obj.view(np.ndarray)}

    def deserializer(data):
        array = data['numpy'].view(CustomNDArray)
        return array

    context = pa.default_serialization_context()

    context.register_type(CustomNDArray, 'CustomNDArray',
                          custom_serializer=serializer,
                          custom_deserializer=deserializer)

    x = CustomNDArray(np.zeros(3))
    serialized = pa.serialize(x, context=context).to_buffer()
    new_x = pa.deserialize(serialized, context=context)
    assert type(new_x) == CustomNDArray
    assert np.alltrue(new_x.view(np.ndarray) == np.zeros(3))

