  else:
    return sum([2**k * scipy.misc.comb(d-1+k, d-1, exact=True)
                for k in range(n)])

def _munp(self, n, c):
    k = arange(0,n+1)
    val = (-1.0/c)**n * sum(comb(n,k)*(-1)**k / (1.0-c*k),axis=0)
    return where(c*n < 1, val, inf)

def _munp(self, n, c):
    k = arange(0,n+1)
    vals = 1.0/c**n * sum(comb(n,k) * (-1)**k * special.gamma(c*k + 1),axis=0)
    return where(c*n > -1, vals, inf)

def _kolmog1(x,n):
    if x <= 0:
        return 0
    if x >= 1:
        return 1
    j = np.arange(np.floor(n*(1-x))+1)
    return 1 - x * np.sum(np.exp(np.log(misc.comb(n,j))
                                       + (n-j) * np.log(1-x-j/float(n))
                                       + (j-1) * np.log(x+j/float(n))))

def marginal_cdf(self, y, n, alpha, beta):
    cdf = 0.0
    for i in range(y + 1):
        cdf += sc.misc.comb(n, y) * beta_fxn(y + alpha, n - y + beta) / beta_fxn(alpha, beta)
    return cdf

def mixture_decomp(w,l):
    k = w.shape[0]
    M = np.zeros((np.round(scipy.misc.comb(k, l)), k))
    i = 0
    for it in itertools.combinations(range(k), l):
        M[i,it] = 1
        i += 1

    (x,res) = scipy.optimize.nnls(M.T, l*w)
    return (M, x)

