def eval(self, data):
    llchildren = np.array([c.eval(data) for c in self.children])

    return scipy.misc.logsumexp(llchildren + self.log_weights, axis=0)

def logsoftmax(x):
    """
    Calculates the log softmax of x, or of the rows of x.
    :param x: vector or matrix
    :return: log softmax
    """

    x = np.asarray(x)

    if x.ndim == 1:
        return x - scipy.misc.logsumexp(x)

    elif x.ndim == 2:
        return x - scipy.misc.logsumexp(x, axis=1)[:, np.newaxis]

    else:
        raise ValueError('input must be either vector or matrix')

