def CCML(ccpart,ccmat,mu,r,nu,s,row_alpha,col_alpha):
	lp = []

	ccmat = np.array(ccmat)

	state = ccpart.states[1]

	# loop through the states
	for state in ccpart.states:
		all_cols = state['col_parts']
		all_rows = state['row_parts']

		K = max(all_cols)+1

		lp_temp = lcrp(all_cols,col_alpha)
		for view in range(K):
			row_part = all_rows[view,:]
			lp_temp += lcrp(row_part,row_alpha)
			cols_view = np.nonzero(all_cols==view)[0]
			for col in cols_view:
				for cat in range(row_part.max()+1):
					X = ccmat[np.nonzero(row_part==cat)[0],col]
					lp_temp += NGML(X,mu,r,nu,s)

		lp.append(lp_temp);

	# return the normalized probabilities
	return lp-sp.misc.logsumexp(lp)

def normalise(a):
    """normalises the input probability vector to sum to one in the log domain.

    This is equivalent to a/sum(a) in the linear domain.
    """
    return a - sp.misc.logsumexp(a)

def dot(a, b):
    """Computes dot product in the log domain.

    This is equivalent to a1*b1+a2*b2+... in the linear domain.
    """
    return sp.misc.logsumexp(a + b)

def logpdf(self, pts, pool=None):
    """Evaluate the logpdf of the KDE at `pts`."""
    logpdfs = [logweight + kde(pts, pool=pool)
               for logweight, kde in zip(self._logweights, self._kdes)]
    if len(pts.shape) == 1:
        return logsumexp(logpdfs)
    else:
        return logsumexp(logpdfs, axis=0)

