def predict_view(self, *args):
    # Regress original given views onto target
    transformed_views = self.transform_view(*args)

    # Get the regression from the training data with available views
    predicted_target = np.mean([transformed_views[i] for i in range(len(args)) if args[i] is not None], axis=0)

    predicted_views = []
    for i, view in enumerate(args):
        if view is None:
            predicted_views.append(predicted_target @ pinv2(self.weights_list[i]))
        else:
            predicted_views.append(view)
    for i, predicted_view in enumerate(predicted_views):
        predicted_views[i] += self.dataset_means[i]
    return predicted_views

def _compute_gravity(self):
    # Calculate the gravity of the planet, based on a density profile.
    # There is a check of the surface value is within reason for this
    # model, otherwise values for PREM are used.

    density = self.table_density[::-1]

    if len(density) > 0:
        radii = self.table_radius[::-1]
        g = scipy.integrate.cumtrapz(
            constants.G * 4.0 * np.pi * density * radii * radii, x=radii, initial=0
        )
        g[1:] = g[1:] / radii[1:] / radii[1:]

        self.table_gravity = g[::-1]
    else:
        raise ValueError(
            "Density profile is an empty list " "in this SeismicTable instance."
        )

def fit_bounded_keelin_3(a, grids, pdfs):

    import scipy.integrate as igt

    cdfs = igt.cumtrapz(pdfs, grids, initial = 0)

    if cdfs.ndim == 1:
        cdfs  = cdfs[np.newaxis, :]
        grids = grids[np.newaxis, :]


    cdfs =  cdfs / ((cdfs[:, -1])[:, np.newaxis])

    ret = np.zeros((cdfs.shape[0], 5))

    for i, quant in enumerate([0.001, a, 0.5, 1-a, 0.999]):

        for row in np.arange(cdfs.shape[0]):

            ret[row, i] = grids[row, np.searchsorted(cdfs[row], quant)]

    return ret

