def integrate(integrand, mn, mx, dx, inttype="trapz"):
    if inttype is "simp":
        from scipy.integrate import simps
        return np.array([0] + [simps(integrand[mn:n], dx=dx, even="first") 
                       for n in range(mn+1,mx)])
    elif inttype is "trapz":
        return np.array([np.trapz(integrand[mn:n], dx=dx) 
                       for n in range(mn,mx)])
    else:
        raise IOError("inttype should be simp or trapz")

def get_initializations(self, num_pol=5, copy_fun='relu'):
    k = []
    if copy_fun == 'relu':
        for n in range(num_pol):
            if n == 0:
                k.append(1.0 / np.sqrt(2 * np.pi))
            elif n == 1:
                k.append(1.0 / 2)
            elif n == 2:
                k.append(1.0 / np.sqrt(4 * np.pi))
            elif n > 2 and n % 2 == 0:
                c = 1.0 * factorial2(n - 3)**2 / np.sqrt(
                    2 * np.pi * np.math.factorial(n))
                k.append(c)
            elif n >= 2 and n % 2 != 0:
                k.append(0.0)
    return k

