def compute_L2_error(self, n, rates):
    from scipy.integrate import odeint, trapz
    bfc = self._bfc

    def fun(data, _):
        theta = np.array([f(data) for f in bfc.functions])
        return np.matmul(rates, theta)

    def fun_reference(data, _):
        theta = np.array([f(data) for f in bfc.functions])
        return np.matmul(self._desired_rates, theta)

    traj = self.get_traj(n)
    xs = traj.times
    num_solution = np.array(odeint(fun, self.initial_states[n].squeeze(), xs)).squeeze()
    reference_soln = np.array(odeint(fun_reference, np.array(self.initial_states[n]).squeeze(), xs)).squeeze()

    err = 0.
    for i in range(traj.n_species):
        err += trapz(np.abs(num_solution[:, i] - reference_soln[:, i]), x=xs)
    return err

def _guess_area(bands, intensities, loc):
  idx = np.searchsorted(bands, loc)
  i, j = max(0, idx-4), idx+5
  area_guess = scipy.integrate.trapz(intensities[i:j], bands[i:j])
  return max(0, area_guess)

def expected_cumulative_spectral_distribution(self, lam, precision=PRECISION, accumulate=False):
    if lam < self.min_lam:
        return 0.

    lams = self.generate_lams(lam, precision)

    singular_mass = self.expected_spectral_singular_mass()
    density_values = [self.expected_spectral_density(lam) for lam in lams]
    if not accumulate:
        accumulated_density = scipy.integrate.trapz(density_values, lams)
        return ((lam >= 0) * singular_mass) + accumulated_density
    else:
        accumulated_densities = scipy.integrate.cumtrapz(density_values, lams)
        accumulated_masses = singular_mass * (lams[1:] >= 0) + accumulated_densities
        return accumulated_masses

